<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import AnalysisChart from './AnalysisChart.vue';
const props=defineProps<{result:any;condition?:string}>();
const tab=ref('结果总览');const range=ref<[number,number]>([0,100]);
watch(()=>props.result?.id,()=>{tab.value='结果总览';range.value=[0,100]});
const rows=computed<any[]>(()=>props.result?.rows||[]);
const labels=computed(()=>rows.value.map(r=>r.timestamp));
const tabs=computed(()=>['结果总览','供需分析','资源出力',...(props.result?.model==='case33'?['网络结果']:[])]);
function values(key:string,scale=1){return rows.value.map(r=>typeof r[key]==='number'&&Number.isFinite(r[key])?r[key]*scale:null)}
function series(items:string[][]){return items.filter(([,k])=>rows.value.some(r=>typeof r[k]==='number')).map(([name,key])=>({name,data:values(key)}))}
const supply=computed(()=>series([['负荷','load_kw'],['实际供电','load_served_kw'],['缺供功率','power_deficit_kw']]));
const resources=computed(()=>series([['外部供电','firm_grid_dispatch_kw'],['应急发电','emergency_gen_kw'],['储能放电','storage_discharge_kw'],['储能充电','storage_charge_kw'],['风光可用','available_re_kw']]));
const voltage=computed(()=>series([['最低电压','ac_min_voltage_pu'],['最高电压','ac_max_voltage_pu']]));
const phases=computed<any[]>(()=>props.result?.phase_metrics||[]);
const metricDefinitions=[['loss_of_load_probability','缺供时段占比','%',100],['curtailment_probability','弃电时段占比','%',100],['max_power_deficit_kw','最大功率缺额','MW',.001],['max_curtailment_kw','最大弃电功率','MW',.001],['expected_energy_deficit_kwh','累计缺供电量','MWh',.001],['expected_curtailment_energy_kwh','累计弃电电量','MWh',.001]] as const;
const cards=computed(()=>metricDefinitions.filter(([key])=>typeof props.result?.metrics?.[key]==='number').map(([key,label,unit,scale])=>({key,label,unit,value:(props.result.metrics[key]*scale).toFixed(3)})));
</script>
<template><div class="balance-overview" v-if="result"><div class="result-context"><strong>{{result.model==='case33'?'网络平衡':'汇总平衡'}} · 任务 {{result.id?.slice(0,8)}}</strong><span>工程版本 {{result.project_revision??'未记录'}} · {{labels[0]}} — {{labels[labels.length-1]}}</span></div><nav class="fixed-tabs" aria-label="平衡结果视图"><button v-for="name in tabs" :key="name" :class="{active:tab===name}" @click="tab=name">{{name}}</button><a :href="'/api/runs/'+result.id+'/csv'">导出逐时结果</a><a :href="'/api/runs/'+result.id+'/report'">导出报告</a></nav><p class="scope-note">当前为单条轨迹：时段占比与累计电量不代表多样本概率或期望值。工况以本任务输入快照为准。</p><div v-if="tab==='结果总览'" class="compact-metrics"><div v-for="c in cards" :key="c.key"><span>{{c.label}}</span><strong>{{c.value}} <small>{{c.unit}}</small></strong></div></div><div class="analysis-grid" :class="{detail:tab!=='结果总览'}"><AnalysisChart v-if="['结果总览','供需分析'].includes(tab)" class="major" title="供需平衡" :labels="labels" unit="MW" :range="range" @range="range=$event" :key="'supply-'+tab" v-bind="{series:supply.map(s=>({...s,data:s.data.map(v=>v===null?null:v/1000)}))}"/><AnalysisChart v-if="['结果总览','供需分析'].includes(tab)" title="储能 SOC" :labels="labels" :series="[{name:'SOC',data:values('soc',100)}]" unit="%" :min="0" :max="100" :range="range" @range="range=$event"/><AnalysisChart v-if="tab==='结果总览'&&phases.length" title="分阶段缺供电量" :labels="phases.map(p=>p.stage)" :series="[{name:'缺供电量',type:'bar',data:phases.map(p=>typeof p.expected_energy_not_served_mwh==='number'?p.expected_energy_not_served_mwh:null)}]" unit="MWh"/><AnalysisChart v-if="['结果总览','资源出力'].includes(tab)" title="资源逐时出力（充电单独正值列示）" :labels="labels" :series="resources" unit="kW" :range="range" @range="range=$event"/><AnalysisChart v-if="tab==='网络结果'" title="网络电压范围" :labels="labels" :series="voltage" unit="pu" :range="range" @range="range=$event"/></div></div></template>
<style scoped>
.balance-overview{padding:14px 0}.result-context{display:flex;justify-content:space-between;gap:14px;font-size:12px;color:#71819a}.result-context strong{color:#172943}.fixed-tabs{display:flex;align-items:center;gap:12px;border-bottom:1px solid #e4e9f0;margin:12px 0}.fixed-tabs button{border:0;border-radius:0!important;background:transparent!important;padding:10px 12px;border-bottom:2px solid transparent}.fixed-tabs button.active{color:#245fd6!important;border-bottom-color:#245fd6}.fixed-tabs a{font-size:12px}.scope-note{font-size:12px;margin:8px 0;color:#71819a}.compact-metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin-bottom:14px}.compact-metrics>div{border:1px solid #e4e9f0;border-radius:8px;background:#fff;padding:12px}.compact-metrics span{font-size:12px;color:#71819a}.compact-metrics strong{display:block;color:#172943;font-size:21px;margin-top:8px}.compact-metrics small{font-size:11px;font-weight:400}.analysis-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(0,1fr);gap:14px}.analysis-grid.detail{grid-template-columns:1fr}.detail :deep(.analysis-plot){height:380px}@media(max-width:1050px){.compact-metrics{grid-template-columns:repeat(3,1fr)}}
</style>
